using CmsWebhook.Domain;

namespace CmsWebhook.Application;

/// <summary>
/// Port for persisting <see cref="CmsEvent"/> rows in the event log (outbox) and advancing their status.
/// </summary>
/// <remarks>
/// Clean architecture: the Application layer depends on this port, never on EF Core. The outbox is an
/// audit log — every accepted delivery is appended (no insert-time dedup); idempotency is enforced at
/// processing time (design D5/D8).
/// </remarks>
public interface ICmsEventLogRepository
{
    /// <summary>
    /// Records the given events with status <see cref="CmsEventStatus.Pending"/>.
    /// </summary>
    /// <param name="events">The validated events to record.</param>
    /// <param name="cancellationToken">Cancellation token.</param>
    Task AddAsync(IReadOnlyCollection<CmsEvent> events, CancellationToken cancellationToken);

    /// <summary>
    /// Loads all events still awaiting processing, oldest first.
    /// </summary>
    /// <param name="cancellationToken">Cancellation token.</param>
    /// <returns>The pending events ordered by their log id.</returns>
    Task<IReadOnlyList<CmsEvent>> GetPendingAsync(CancellationToken cancellationToken);

    /// <summary>
    /// Returns whether an event with the same entity id, type and version has already been processed.
    /// </summary>
    /// <param name="entityId">The entity the event refers to.</param>
    /// <param name="type">The event type.</param>
    /// <param name="version">The event version, or <see langword="null"/> for delete events.</param>
    /// <param name="cancellationToken">Cancellation token.</param>
    /// <returns><see langword="true"/> when an identical tuple was already processed.</returns>
    Task<bool> ExistsProcessedAsync(string entityId, CmsEventType type, int? version, CancellationToken cancellationToken);

    /// <summary>
    /// Marks the given event as processed.
    /// </summary>
    /// <param name="eventId">The event's log id.</param>
    /// <param name="processedAt">When processing completed.</param>
    /// <param name="cancellationToken">Cancellation token.</param>
    Task MarkProcessedAsync(long eventId, DateTimeOffset processedAt, CancellationToken cancellationToken);

    /// <summary>
    /// Marks the given event as failed, recording the error.
    /// </summary>
    /// <param name="eventId">The event's log id.</param>
    /// <param name="error">The failure message to record.</param>
    /// <param name="processedAt">When processing completed.</param>
    /// <param name="cancellationToken">Cancellation token.</param>
    Task MarkFailedAsync(long eventId, string error, DateTimeOffset processedAt, CancellationToken cancellationToken);
}

using System.Data.Common;
using Microsoft.EntityFrameworkCore;

namespace QueueApi.Auth;

/// <summary>
/// Verifies credentials against the shared database-backed credential store.
/// </summary>
/// <remarks>
/// Spec "Credentials are sourced from the credential store": the store is the source of truth for
/// credentials. Spec "Passwords are verified against stored hashes": the presented password is
/// re-derived with the stored salt and compared in constant time by
/// <see cref="Pbkdf2PasswordHasher.Verify(string, string)"/>. An unreachable or uninitialized store
/// surfaces as an <see cref="InvalidOperationException"/> with setup guidance instead of a cryptic
/// SQL error (design decision D7). Failures are caught via <see cref="DbException"/>, the base class of
/// every ADO.NET provider's connection errors, so the wrapping stays correct when the SQLite provider
/// is swapped for another engine (design decision D1).
/// </remarks>
public class DbUserCredentialsProvider : IUserCredentialsProvider
{
    private readonly AuthDbContext _dbContext;

    /// <summary>
    /// Creates the provider backed by the given credential store context.
    /// </summary>
    /// <param name="dbContext">The context exposing the credential store's <c>Users</c> table.</param>
    public DbUserCredentialsProvider(AuthDbContext dbContext)
    {
        _dbContext = dbContext;
    }

    /// <inheritdoc/>
    public async Task<bool> VerifyCredentialsAsync(string username, string password)
    {
        var user = await FindUserAsync(username);
        if (user is null)
        {
            return false;
        }

        return Pbkdf2PasswordHasher.Verify(password, user.PasswordHash);
    }

    /// <inheritdoc/>
    public async Task<bool> UserExistsAsync(string username)
    {
        try
        {
            return await _dbContext.Users.AnyAsync(user => user.Username == username);
        }
        catch (DbException exception)
        {
            throw CreateStoreUnavailableException(exception);
        }
    }

    private async Task<UserCredential?> FindUserAsync(string username)
    {
        try
        {
            return await _dbContext.Users.SingleOrDefaultAsync(user => user.Username == username);
        }
        catch (DbException exception)
        {
            throw CreateStoreUnavailableException(exception);
        }
    }

    private static InvalidOperationException CreateStoreUnavailableException(DbException exception)
        => new(
            "The credential store could not be accessed. Make sure the database exists and has been "
            + "initialized by running 'scripts/init-db.sh' from the repository root.",
            exception);
}

using System.Security.Claims;
using System.Text;
using System.Text.Encodings.Web;
using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

namespace QueueApi.Auth;

/// <summary>
/// Authenticates requests that present HTTP Basic credentials.
/// </summary>
/// <remarks>
/// Spec "All endpoints require authentication": a missing <c>Authorization</c> header, an unsupported scheme,
/// undecodable credentials, an unknown username or a wrong password produce a failed result that the
/// authorization middleware turns into <c>401</c>, and the challenge advertises the <c>Basic</c> scheme so
/// clients know how to authenticate. Passwords are verified against the stored PBKDF2 hash through the
/// credential provider seam — never compared as plaintext — and an unknown user is indistinguishable from a
/// wrong password (spec "Passwords are verified against stored hashes", design decision D3).
/// </remarks>
public class BasicAuthenticationHandler : AuthenticationHandler<BasicAuthenticationOptions>
{
    private const string BasicSchemePrefix = "Basic ";
    private readonly IUserCredentialsProvider _credentialsProvider;

    /// <summary>
    /// Creates the handler with the given options monitor, logger factory, URL encoder and credential provider.
    /// </summary>
    /// <param name="options">The options monitor providing the scheme's <see cref="BasicAuthenticationOptions"/>.</param>
    /// <param name="logger">The logger factory used to obtain the handler's logger.</param>
    /// <param name="encoder">The URL encoder used by the base class.</param>
    /// <param name="credentialsProvider">The provider that verifies usernames against passwords.</param>
    public BasicAuthenticationHandler(
        IOptionsMonitor<BasicAuthenticationOptions> options,
        ILoggerFactory logger,
        UrlEncoder encoder,
        IUserCredentialsProvider credentialsProvider)
        : base(options, logger, encoder)
    {
        _credentialsProvider = credentialsProvider;
    }

    /// <inheritdoc/>
    protected override async Task<AuthenticateResult> HandleAuthenticateAsync()
    {
        if (!Request.Headers.TryGetValue("Authorization", out var authorizationHeader)
            || string.IsNullOrWhiteSpace(authorizationHeader))
        {
            Logger.LogWarning("Basic authentication rejected: missing Authorization header.");
            return AuthenticateResult.NoResult();
        }

        var headerValue = authorizationHeader.ToString();
        if (!headerValue.StartsWith(BasicSchemePrefix, StringComparison.OrdinalIgnoreCase))
        {
            Logger.LogWarning("Basic authentication rejected: unsupported authorization scheme.");
            return AuthenticateResult.Fail("Unsupported authorization scheme.");
        }

        var decodedCredentials = DecodeCredentials(headerValue[BasicSchemePrefix.Length..].Trim());
        if (decodedCredentials is null)
        {
            Logger.LogWarning("Basic authentication rejected: malformed Basic credentials.");
            return AuthenticateResult.Fail("Malformed Basic credentials.");
        }

        var separatorIndex = decodedCredentials.IndexOf(':');
        if (separatorIndex < 0)
        {
            Logger.LogWarning("Basic authentication rejected: malformed Basic credentials.");
            return AuthenticateResult.Fail("Malformed Basic credentials.");
        }

        var username = decodedCredentials[..separatorIndex];
        var password = decodedCredentials[(separatorIndex + 1)..];

        var credentialsValid = await _credentialsProvider.VerifyCredentialsAsync(username, password);
        if (!credentialsValid)
        {
            Logger.LogWarning(
                "Basic authentication rejected for username '{Username}': unknown user or invalid password.",
                username);
            return AuthenticateResult.Fail("Invalid credentials.");
        }

        var claims = new[]
        {
            new Claim(ClaimTypes.Name, username),
        };
        var identity = new ClaimsIdentity(claims, Scheme.Name);
        var principal = new ClaimsPrincipal(identity);
        var ticket = new AuthenticationTicket(principal, Scheme.Name);

        Logger.LogInformation("Basic authentication succeeded for username '{Username}'.", username);
        return AuthenticateResult.Success(ticket);
    }

    /// <inheritdoc/>
    protected override Task HandleChallengeAsync(AuthenticationProperties properties)
    {
        Response.StatusCode = StatusCodes.Status401Unauthorized;
        Response.Headers.WWWAuthenticate = $"Basic realm=\"{Options.Realm}\"";
        return Task.CompletedTask;
    }

    private static string? DecodeCredentials(string base64Value)
    {
        try
        {
            return Encoding.UTF8.GetString(Convert.FromBase64String(base64Value));
        }
        catch (FormatException)
        {
            return null;
        }
    }
}

using CmsWebhook.Domain;
using Microsoft.EntityFrameworkCore;

namespace CmsWebhook.Infrastructure;

/// <summary>
/// EF Core context for the dedicated CMS database holding the event log (outbox) and the entity store.
/// </summary>
/// <remarks>
/// Design D3/D8: the CMS database is independent of the shared auth credential store, configured via
/// <c>ConnectionStrings:CmsDb</c> and provider-neutral EF Core code (swapping engines later is a provider
/// + connection-string change). The outbox (<c>cms_event_log</c>) is an append-only audit of accepted
/// deliveries; the <c>cms_entities</c> table is the processed state the deferred Users API will read.
/// </remarks>
public class CmsDbContext : DbContext
{
    /// <summary>
    /// Creates the context with the given options.
    /// </summary>
    /// <param name="options">The options carrying the database provider and connection string.</param>
    public CmsDbContext(DbContextOptions<CmsDbContext> options)
        : base(options)
    {
    }

    /// <summary>
    /// The outbox rows of received CMS events.
    /// </summary>
    public DbSet<CmsEvent> Events => Set<CmsEvent>();

    /// <summary>
    /// The processed entity store.
    /// </summary>
    public DbSet<CmsEntity> Entities => Set<CmsEntity>();

    /// <inheritdoc/>
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<CmsEvent>(entity =>
        {
            entity.ToTable("cms_event_log");
            entity.HasKey(item => item.Id);
            entity.Property(item => item.EntityId).HasColumnName("entity_id").IsRequired();
            entity.Property(item => item.Type).HasColumnName("event_type").IsRequired().HasConversion<string>().HasMaxLength(16);
            entity.Property(item => item.Version).HasColumnName("version");
            entity.Property(item => item.Payload).HasColumnName("payload_json");
            entity.Property(item => item.Timestamp).HasColumnName("timestamp");
            entity.Property(item => item.ReceivedAt).HasColumnName("received_at");
            entity.Property(item => item.Status).HasColumnName("status").IsRequired().HasConversion<string>().HasMaxLength(16);
            entity.Property(item => item.Error).HasColumnName("error");
            entity.Property(item => item.ProcessedAt).HasColumnName("processed_at");
            entity.HasIndex(item => item.Status);
        });

        modelBuilder.Entity<CmsEntity>(entity =>
        {
            entity.ToTable("cms_entities");
            entity.HasKey(item => item.Id);
            entity.Property(item => item.LatestVersion).HasColumnName("latest_version");
            entity.Property(item => item.Payload).HasColumnName("payload_json").IsRequired();
            entity.Property(item => item.IsPublished).HasColumnName("is_published");
            entity.Property(item => item.IsVisibleByAdmin).HasColumnName("is_visible_by_admin");
            entity.Property(item => item.UpdatedAt).HasColumnName("updated_at");
        });
    }
}

using CmsWebhook.Application;
using CmsWebhook.Domain;
using Microsoft.EntityFrameworkCore;

namespace CmsWebhook.Infrastructure;

/// <summary>
/// EF Core implementation of <see cref="ICmsEventLogRepository"/> over the <c>cms_event_log</c> table.
/// </summary>
/// <remarks>
/// All writes participate in the caller's ambient transaction (the outbox worker opens one per event),
/// so the entity update and the event status change commit atomically (design D5). The query for pending
/// events is indexed on <see cref="CmsEventStatus.Pending"/> and ordered by log id for FIFO processing.
/// </remarks>
public class EfCmsEventLogRepository : ICmsEventLogRepository
{
    private readonly CmsDbContext _dbContext;

    /// <summary>
    /// Creates the repository over the given context.
    /// </summary>
    /// <param name="dbContext">The context exposing the event log table.</param>
    public EfCmsEventLogRepository(CmsDbContext dbContext)
    {
        _dbContext = dbContext;
    }

    /// <inheritdoc/>
    public async Task AddAsync(IReadOnlyCollection<CmsEvent> events, CancellationToken cancellationToken)
    {
        _dbContext.Events.AddRange(events);
        await _dbContext.SaveChangesAsync(cancellationToken);
    }

    /// <inheritdoc/>
    public async Task<IReadOnlyList<CmsEvent>> GetPendingAsync(CancellationToken cancellationToken)
        => await _dbContext.Events
            .Where(item => item.Status == CmsEventStatus.Pending)
            .OrderBy(item => item.Id)
            .ToListAsync(cancellationToken);

    /// <inheritdoc/>
    public async Task<bool> ExistsProcessedAsync(
        string entityId,
        CmsEventType type,
        int? version,
        CancellationToken cancellationToken)
        => await _dbContext.Events.AnyAsync(
            item => item.EntityId == entityId
                && item.Type == type
                && item.Version == version
                && item.Status == CmsEventStatus.Processed,
            cancellationToken);

    /// <inheritdoc/>
    public async Task MarkProcessedAsync(long eventId, DateTimeOffset processedAt, CancellationToken cancellationToken)
        => await UpdateStatusAsync(eventId, CmsEventStatus.Processed, processedAt, error: null, cancellationToken);

    /// <inheritdoc/>
    public async Task MarkFailedAsync(long eventId, string error, DateTimeOffset processedAt, CancellationToken cancellationToken)
        => await UpdateStatusAsync(eventId, CmsEventStatus.Failed, processedAt, error, cancellationToken);

    private async Task UpdateStatusAsync(
        long eventId,
        CmsEventStatus status,
        DateTimeOffset processedAt,
        string? error,
        CancellationToken cancellationToken)
    {
        var @event = await _dbContext.Events.FindAsync(new object[] { eventId }, cancellationToken);
        if (@event is null)
        {
            return;
        }

        @event.Status = status;
        @event.ProcessedAt = processedAt;
        @event.Error = error;
        await _dbContext.SaveChangesAsync(cancellationToken);
    }
}

using CmsWebhook.Application;
using CmsWebhook.Domain;
using Microsoft.EntityFrameworkCore;

namespace CmsWebhook.Infrastructure;

/// <summary>
/// EF Core implementation of <see cref="ICmsEntityRepository"/> over the <c>cms_entities</c> table.
/// </summary>
/// <remarks>
/// Writes participate in the outbox worker's per-event transaction (design D5). The upsert loads the
/// tracked row when present so EF updates it in place instead of erroring on a duplicate key.
/// </remarks>
public class EfCmsEntityRepository : ICmsEntityRepository
{
    private readonly CmsDbContext _dbContext;

    /// <summary>
    /// Creates the repository over the given context.
    /// </summary>
    /// <param name="dbContext">The context exposing the entity store table.</param>
    public EfCmsEntityRepository(CmsDbContext dbContext)
    {
        _dbContext = dbContext;
    }

    /// <inheritdoc/>
    public async Task<CmsEntity?> GetByIdAsync(string id, CancellationToken cancellationToken)
        => await _dbContext.Entities.SingleOrDefaultAsync(item => item.Id == id, cancellationToken);

    /// <inheritdoc/>
    public async Task UpsertAsync(CmsEntity entity, CancellationToken cancellationToken)
    {
        var existing = await _dbContext.Entities.FindAsync(new object[] { entity.Id }, cancellationToken);
        if (existing is null)
        {
            _dbContext.Entities.Add(entity);
        }
        else
        {
            _dbContext.Entry(existing).CurrentValues.SetValues(entity);
        }

        await _dbContext.SaveChangesAsync(cancellationToken);
    }

    /// <inheritdoc/>
    public async Task DeleteAsync(string id, CancellationToken cancellationToken)
    {
        var existing = await _dbContext.Entities.FindAsync(new object[] { id }, cancellationToken);
        if (existing is not null)
        {
            _dbContext.Entities.Remove(existing);
            await _dbContext.SaveChangesAsync(cancellationToken);
        }
    }
}

using CmsWebhook.Domain;

namespace CmsWebhook.Application;

/// <summary>
/// Port for reading and writing stored <see cref="CmsEntity"/> records.
/// </summary>
/// <remarks>
/// Clean architecture: the Application layer depends on this port, never on EF Core. Writes are applied
/// by the outbox worker inside the per-event transaction (design D5).
/// </remarks>
public interface ICmsEntityRepository
{
    /// <summary>
    /// Loads the stored entity for the given id, or <see langword="null"/> when none exists.
    /// </summary>
    /// <param name="id">The external entity's id.</param>
    /// <param name="cancellationToken">Cancellation token.</param>
    Task<CmsEntity?> GetByIdAsync(string id, CancellationToken cancellationToken);

    /// <summary>
    /// Inserts the entity or updates it in place when it already exists.
    /// </summary>
    /// <param name="entity">The entity state to persist.</param>
    /// <param name="cancellationToken">Cancellation token.</param>
    Task UpsertAsync(CmsEntity entity, CancellationToken cancellationToken);

    /// <summary>
    /// Hard-deletes the stored entity for the given id; a missing entity is a no-op.
    /// </summary>
    /// <param name="id">The external entity's id.</param>
    /// <param name="cancellationToken">Cancellation token.</param>
    Task DeleteAsync(string id, CancellationToken cancellationToken);
}

using System.Text.Json;
using CmsWebhook.Application;
using CmsWebhook.Domain;

namespace CmsWebhook.Api.Endpoints;

/// <summary>
/// Registers the CMS event ingestion endpoints.
/// </summary>
/// <remarks>
/// The <c>/cms/events</c> handler moved here from <c>Program.cs</c> so each feature owns its endpoint
/// mapping and its OpenAPI metadata (design decision D2 of change add-healthcheck-and-openapi). The
/// endpoint's behavior is unchanged; this is a behavior-neutral reorganization.
/// </remarks>
public static class CmsEventEndpoints
{
    /// <summary>
    /// Maps the <c>POST /cms/events</c> ingestion endpoint.
    /// </summary>
    /// <param name="endpoints">The endpoint route builder to register the endpoint on.</param>
    /// <returns>The endpoint route builder for chaining.</returns>
    public static IEndpointRouteBuilder MapCmsEventEndpoints(this IEndpointRouteBuilder endpoints)
    {
        endpoints.MapPost("/cms/events", IngestAsync)
            .WithSummary("Ingest CMS events")
            .WithDescription("Accepts a single CMS event or a batch of events, records them in the outbox, and returns 201 when accepted.")
            .WithTags("cms-events");

        return endpoints;
    }

    /// <summary>
    /// Handles the <c>POST /cms/events</c> request: parses the body, deserializes and validates it, and
    /// records the accepted events before responding.
    /// </summary>
    /// <param name="request">The HTTP request carrying the JSON body.</param>
    /// <param name="handler">The command handler that records the accepted events.</param>
    /// <param name="cancellationToken">The request cancellation token.</param>
    /// <returns><c>201 Created</c> on acceptance, otherwise <c>400 Bad Request</c>.</returns>
    private static async Task<IResult> IngestAsync(
        HttpRequest request,
        IIngestCmsEventsCommandHandler handler,
        CancellationToken cancellationToken)
    {
        JsonDocument? document = null;
        try
        {
            document = await JsonDocument.ParseAsync(request.Body, cancellationToken: cancellationToken);
        }
        catch (JsonException)
        {
            return Results.BadRequest();
        }

        // The document must stay alive while requests are deserialized and validated: CmsRequest payloads
        // are JsonElements referencing its memory, and the validator reads them via GetRawText().
        using (document)
        {
            IReadOnlyList<CmsRequest?>? requests;
            try
            {
                var root = document.RootElement;
                requests = root.ValueKind switch
                {
                    JsonValueKind.Object => new[] { DeserializeCmsRequest(root) },
                    JsonValueKind.Array => DeserializeCmsRequestBatch(root),
                    _ => null,
                };
            }
            catch (JsonException)
            {
                // Unparseable or wrongly-typed fields (e.g. "type": 5) are client errors, not server errors.
                return Results.BadRequest();
            }

            if (requests is null || requests.Any(item => item is null))
            {
                return Results.BadRequest();
            }

            var result = await handler.HandleAsync(requests.Cast<CmsRequest>().ToList(), cancellationToken);
            return result.Success ? Results.StatusCode(StatusCodes.Status201Created) : Results.BadRequest();
        }
    }

    /// <summary>
    /// Deserializes a single CMS request from the parsed JSON body.
    /// </summary>
    /// <param name="element">The JSON object to deserialize.</param>
    /// <returns>The deserialized request, or <see langword="null"/> when the element is null.</returns>
    private static CmsRequest? DeserializeCmsRequest(JsonElement element)
        => element.Deserialize<CmsRequest>();

    /// <summary>
    /// Deserializes a batch of CMS requests from the parsed JSON body.
    /// </summary>
    /// <param name="element">The JSON array to deserialize.</param>
    /// <returns>The deserialized requests; null elements (invalid batch members) are kept for validation.</returns>
    private static IReadOnlyList<CmsRequest?>? DeserializeCmsRequestBatch(JsonElement element)
        => element.Deserialize<List<CmsRequest?>>();
}

namespace QueueApi.Auth;

/// <summary>
/// Default values shared by the Basic authentication components of <c>QueueApi.Auth</c>.
/// </summary>
public static class BasicAuthenticationDefaults
{
    /// <summary>
    /// The name of the Basic authentication scheme registered by the <c>QueueApi.Auth</c> DI extension.
    /// </summary>
    /// <remarks>
    /// The scheme name is arbitrary as long as it is used consistently by the scheme registration,
    /// the authentication ticket and the challenge/forbid flow (design decision: "Scheme/option shape").
    /// </remarks>
    public const string AuthenticationScheme = "BasicAuth";
}

using Microsoft.AspNetCore.Authentication;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Options;

namespace QueueApi.Auth;

/// <summary>
/// Dependency injection registration helpers for the Basic authentication scheme.
/// </summary>
public static class BasicAuthenticationServiceCollectionExtensions
{
    /// <summary>
    /// Registers the Basic authentication scheme, the database-backed credential provider and options validation.
    /// </summary>
    /// <param name="services">The application's service collection.</param>
    /// <param name="connectionString">The connection string for the shared credential store.</param>
    /// <returns>The same <paramref name="services"/> for chaining.</returns>
    /// <remarks>
    /// Spec "Credential store location is configurable": the connection string is supplied by the caller from
    /// configuration, keeping the shared library free of configuration-coupling. The scheme is registered as the
    /// default authenticate and challenge scheme so that <c>ChallengeAsync</c> (issued by the authorization
    /// middleware for <c>401</c>) routes to the Basic handler. Options validation runs at startup
    /// (design decision 4 of the original change: fail fast on misconfiguration).
    /// </remarks>
    public static IServiceCollection AddBasicAuthentication(this IServiceCollection services, string connectionString)
    {
        services.AddDbContext<AuthDbContext>(options => options.UseSqlite(connectionString));
        services.AddScoped<IUserCredentialsProvider, DbUserCredentialsProvider>();

        services.AddOptions<BasicAuthenticationOptions>()
            .Validate(options => !string.IsNullOrWhiteSpace(options.Realm),
                $"{nameof(BasicAuthenticationOptions.Realm)} must not be empty.")
            .ValidateOnStart();

        services.AddAuthentication(options =>
            {
                options.DefaultAuthenticateScheme = BasicAuthenticationDefaults.AuthenticationScheme;
                options.DefaultChallengeScheme = BasicAuthenticationDefaults.AuthenticationScheme;
                options.DefaultForbidScheme = BasicAuthenticationDefaults.AuthenticationScheme;
            })
            .AddScheme<BasicAuthenticationOptions, BasicAuthenticationHandler>(
                BasicAuthenticationDefaults.AuthenticationScheme,
                configureOptions: null);

        return services;
    }
}

using Microsoft.EntityFrameworkCore;

namespace QueueApi.Auth;

/// <summary>
/// EF Core context for the shared database-backed credential store.
/// </summary>
/// <remarks>
/// Spec "Credential store location is configurable": the context is provider-neutral EF Core code
/// configured with the SQLite provider at registration time, so swapping the database engine is a
/// provider + connection-string change (design decision D1). The single <c>Users</c> table is shared
/// by all APIs consuming <c>QueueApi.Auth</c>.
/// </remarks>
public class AuthDbContext : DbContext
{
    /// <summary>
    /// Creates the context with the given options.
    /// </summary>
    /// <param name="options">The options carrying the database provider and connection string.</param>
    public AuthDbContext(DbContextOptions<AuthDbContext> options)
        : base(options)
    {
    }

    /// <summary>
    /// The users registered in the credential store.
    /// </summary>
    public DbSet<UserCredential> Users => Set<UserCredential>();

    /// <inheritdoc/>
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<UserCredential>(entity =>
        {
            entity.ToTable("Users");
            entity.HasKey(user => user.Id);
            entity.Property(user => user.Username).HasColumnName("username").IsRequired().HasMaxLength(20);
            entity.HasIndex(user => user.Username).IsUnique();
            entity.Property(user => user.PasswordHash).HasColumnName("password_hash").IsRequired();
        });
    }
}

using Microsoft.AspNetCore.Authentication;

namespace QueueApi.Auth;

/// <summary>
/// Options for the Basic authentication scheme implemented by <see cref="BasicAuthenticationHandler"/>.
/// </summary>
/// <remarks>
/// Carries only presentation-level settings; user credentials are resolved at runtime through
/// <see cref="IUserCredentialsProvider"/>, keeping the handler generic and reusable across APIs
/// (architecture: both APIs share the same Basic Auth implementation).
/// </remarks>
public class BasicAuthenticationOptions : AuthenticationSchemeOptions
{
    /// <summary>
    /// The realm advertised in the <c>WWW-Authenticate: Basic</c> challenge header.
    /// </summary>
    /// <value>Defaults to <c>"QueueApi"</c>; must not be empty for the challenge header to be valid.</value>
    public string Realm { get; set; } = "QueueApi";
}

namespace CmsWebhook.Domain;

/// <summary>
/// The system's internal representation of an entity from the external CMS.
/// </summary>
/// <remarks>
/// Glossary: a <b>CmsEntity</b> is the internal representation of an entity from the external CMS. It
/// keeps track of the latest data version (initial requirements: "Entities must keep track of the latest
/// data version"), the published flag (set by <c>publish</c>/<c>unPublish</c>, untouched by
/// <c>update</c>) and the administrator's visibility override used by the deferred Users API
/// (defaults to visible; disabling is independent of publishing status).
/// </remarks>
public class CmsEntity
{
    /// <summary>
    /// The external entity's id.
    /// </summary>
    public string Id { get; set; } = string.Empty;

    /// <summary>
    /// The latest version of the entity known to our system.
    /// </summary>
    public int LatestVersion { get; set; }

    /// <summary>
    /// The payload of the latest version, as a raw JSON object string.
    /// </summary>
    public string Payload { get; set; } = string.Empty;

    /// <summary>
    /// Whether the entity is currently published and therefore visible to regular Users.
    /// </summary>
    public bool IsPublished { get; set; }

    /// <summary>
    /// Whether an administrator has disabled this entity from the (future) Users API.
    /// </summary>
    public bool IsVisibleByAdmin { get; set; } = true;

    /// <summary>
    /// When the latest version was last updated, from the event's timestamp.
    /// </summary>
    public DateTimeOffset UpdatedAt { get; set; }
}

using System.Text.Json;
using Microsoft.AspNetCore.Diagnostics.HealthChecks;
using Microsoft.Extensions.Diagnostics.HealthChecks;

namespace CmsWebhook.Api.Endpoints;

/// <summary>
/// Registers the CMS Webhook API's health endpoints.
/// </summary>
/// <remarks>
/// Health is a cross-cutting, feature-level concern with a home of its own so <c>Program.cs</c> stays
/// about composition (design decision D2 of change add-healthcheck-and-openapi).
/// </remarks>
public static class HealthEndpoints
{
    /// <summary>
    /// Maps the anonymous liveness healthcheck at <c>/health</c>.
    /// </summary>
    /// <param name="endpoints">The endpoint route builder to register the endpoint on.</param>
    /// <returns>The endpoint route builder for chaining.</returns>
    public static IEndpointRouteBuilder MapHealthEndpoints(this IEndpointRouteBuilder endpoints)
    {
        endpoints.MapHealthChecks("/health", new HealthCheckOptions
        {
            // The built-in result-status-code mapping (Healthy/Degraded -> 200, Unhealthy -> 503) is kept;
            // this writer only supplies the JSON body the load balancers expect (design decision D1).
            ResponseWriter = WriteJsonResponseAsync,
        }).AllowAnonymous();

        return endpoints;
    }

    /// <summary>
    /// Writes the health report as a JSON body reporting the overall status.
    /// </summary>
    /// <param name="context">The current HTTP context.</param>
    /// <param name="report">The health check report to serialize.</param>
    /// <returns>A task completing once the response body has been written.</returns>
    private static Task WriteJsonResponseAsync(HttpContext context, HealthReport report)
    {
        var status = report.Status == HealthStatus.Healthy ? "Healthy" : "Unhealthy";
        context.Response.ContentType = "application/json";
        return context.Response.WriteAsync(JsonSerializer.Serialize(new { status }));
    }
}

using Microsoft.EntityFrameworkCore;
using QueueApi.Auth;

namespace AuthDbInit;

/// <summary>
/// Initializes the shared credential store schema and seeds a user, idempotently.
/// </summary>
/// <remarks>
/// Spec "Credential store is provisioned by an initialization script": the schema is created when missing
/// (<c>EnsureCreated</c>, per design decision D6 — no migration infrastructure yet) and a user is inserted
/// only when the username is absent, so re-running never duplicates data. Passwords are hashed with the
/// exact helper the APIs verify against (<see cref="Pbkdf2PasswordHasher"/>), keeping seeded hashes
/// compatible (design decision D6).
/// </remarks>
public static class AuthDbInitializer
{
    /// <summary>
    /// Ensures the store schema exists and seeds <paramref name="username"/> when missing.
    /// </summary>
    /// <param name="connectionString">The SQLite connection string of the credential store.</param>
    /// <param name="username">The username to seed.</param>
    /// <param name="password">The plaintext password to hash and store.</param>
    /// <param name="cancellationToken">A token to cancel the operation.</param>
    /// <returns><see cref="InitializationResult.Created"/> when the user was seeded, <see cref="InitializationResult.AlreadyExists"/> otherwise.</returns>
    /// <exception cref="System.Data.Common.DbException">
    /// The store could not be reached while creating the schema or seeding the user (e.g. the
    /// database file is missing or locked).
    /// </exception>
    public static async Task<InitializationResult> InitializeAsync(
        string connectionString,
        string username,
        string password,
        CancellationToken cancellationToken = default)
    {
        var options = new DbContextOptionsBuilder<AuthDbContext>().UseSqlite(connectionString).Options;
        await using var context = new AuthDbContext(options);

        await context.Database.EnsureCreatedAsync(cancellationToken);

        var userExists = await context.Users.AnyAsync(user => user.Username == username, cancellationToken);
        if (userExists)
        {
            return InitializationResult.AlreadyExists;
        }

        context.Users.Add(new UserCredential
        {
            Username = username,
            PasswordHash = Pbkdf2PasswordHasher.Hash(password),
        });
        await context.SaveChangesAsync(cancellationToken);

        return InitializationResult.Created;
    }
}

/// <summary>
/// The outcome of a credential store initialization run.
/// </summary>
public enum InitializationResult
{
    /// <summary>
    /// The user was created by this run.
    /// </summary>
    Created,

    /// <summary>
    /// The user already existed; the store was left unchanged.
    /// </summary>
    AlreadyExists,
}
